3	/// spec-6-4 — a single user-only chat bubble's own bookmark affordance
4	/// (AGENTS.md: "a four-state... idle/saving/saved/error bookmark button to
5	/// user-only chat bubbles"), mirrors `entries/domain/entities/
6	/// sync_badge_state.dart`'s own per-feature placement/shape: sealed, with
7	/// `const factory` constructors on the base class so call sites read as
8	/// `BookmarkState.idle()` rather than naming each subclass directly.
9	/// Never persisted across restarts (Never) — in-memory only, on
10	/// `ChatUiMessage.bookmarkState`.
11	sealed class BookmarkState {
12	  const BookmarkState();
13	
14	  const factory BookmarkState.idle() = BookmarkIdle;
15	
16	  const factory BookmarkState.saving() = BookmarkSaving;
17	
18	  const factory BookmarkState.saved() = BookmarkSaved;
19	
20	  const factory BookmarkState.error(Failure failure) = BookmarkError;
21	}
22	
23	/// The default state — outline icon, tappable.
24	class BookmarkIdle extends BookmarkState {
25	  const BookmarkIdle();
26	
27	  @override
28	  bool operator ==(Object other) => other is BookmarkIdle;
29	
30	  @override
31	  int get hashCode => (BookmarkIdle).hashCode;
32	
33	  @override
34	  String toString() => 'BookmarkIdle()';
35	}
36	
37	/// The save is in flight — spinner (or a static label under Reduce
38	/// Motion, `ChatBubble`'s own concern, not this state's).
39	class BookmarkSaving extends BookmarkState {
40	  const BookmarkSaving();
41	
42	  @override
43	  bool operator ==(Object other) => other is BookmarkSaving;
44	
45	  @override
46	  int get hashCode => (BookmarkSaving).hashCode;
47	
48	  @override
49	  String toString() => 'BookmarkSaving()';
50	}
51	
52	/// The save succeeded — ochre check (`colorAccent`). Tapping an already-
53	/// [BookmarkSaved] bubble is a client-side no-op (Boundaries).
54	class BookmarkSaved extends BookmarkState {
55	  const BookmarkSaved();
56	
57	  @override
58	  bool operator ==(Object other) => other is BookmarkSaved;
59	
60	  @override
61	  int get hashCode => (BookmarkSaved).hashCode;
62	
63	  @override
64	  String toString() => 'BookmarkSaved()';
65	}
66	
67	/// The save failed — red warning, retryable: tapping it re-attempts the
68	/// same save (I/O matrix: "Save fails"). [failure] is kept for parity with
69	/// `SyncBadgeError`'s own shape, even though `ChatBubble` only ever needs
70	/// the state's own identity (icon/color), never [failure]'s own message —
71	/// no UI surface for it exists in this story's Boundaries.
72	class BookmarkError extends BookmarkState {
73	  const BookmarkError(this.failure);
74	
75	  final Failure failure;
76	
77	  @override
78	  bool operator ==(Object other) =>
79	      identical(this, other) ||
80	      (other is BookmarkError && other.failure == failure);
81	
82	  @override
83	  int get hashCode => failure.hashCode;
84	
85	  @override
86	  String toString() => 'BookmarkError(failure: $failure)';
87	}
