1	import 'package:dio/dio.dart';
2	import 'package:flutter_dotenv/flutter_dotenv.dart';
3	import 'package:flutter_secure_storage/flutter_secure_storage.dart';
4	import 'package:get_it/get_it.dart';
5	import 'package:hive_ce_flutter/hive_ce_flutter.dart';
6	
7	import '../../features/account/account_injection.dart';
8	import '../../features/auth/auth_injection.dart';
9	import '../../features/capture/capture_injection.dart';
10	import '../../features/chat/chat_injection.dart';
11	import '../../features/entries/entries_injection.dart';
12	import '../../features/vault/vault_injection.dart';
13	import '../network/access_token_provider.dart';
14	import '../network/api_client.dart';
15	import '../network/header_interceptor.dart';
16	import '../network/retry_interceptor.dart';
17	import '../network/url_builder.dart';
18	import '../session/session_expiry_notifier.dart';
19	
20	/// The project's single `get_it` instance — exactly one DI container exists
21	/// (architecture spine). Every feature's `registerXFeature()` registers
22	/// through this same `sl`, never a second container.
23	final sl = GetIt.instance;
24	
25	/// Bootstraps core infrastructure: loads `.env`, then registers
26	/// `FlutterSecureStorage`, `Dio` (configured with the header + retry
27	/// interceptors) and `ApiClient` through `sl` — the `dio` +
28	/// `flutter_secure_storage` + `get_it` integration spike this story proves
29	/// before anything else is built on top of it.
30	Future<void> setupCoreDependencies() async {
31	  await dotenv.load(fileName: '.env');
32	
33	  final functionsBaseUrl = dotenv.get('FUNCTIONS_BASE_URL');
34	  final supabaseAnonKey = dotenv.get('SUPABASE_ANON_KEY');
35	
36	  sl.registerLazySingleton<FlutterSecureStorage>(
37	    () => const FlutterSecureStorage(),
38	  );
39	
40	  sl.registerLazySingleton<AccessTokenProvider>(
41	    () => SecureStorageAccessTokenProvider(sl<FlutterSecureStorage>()),
42	  );
43	
44	  sl.registerLazySingleton<UrlBuilder>(() => UrlBuilder(functionsBaseUrl));
45	
46	  // Story 1.5 — `dispose:` wires `SessionExpiryNotifier.dispose()` into
47	  // `get_it`'s own reset lifecycle, same rationale as `SessionRepository`'s
48	  // own registration below. Registration order here is cosmetic, not
49	  // load-bearing: `registerLazySingleton` only builds its instance on first
50	  // `sl<T>()` access, so `ApiClient`'s factory can resolve this dependency
51	  // correctly regardless of which of the two is registered first.
52	  sl.registerLazySingleton<SessionExpiryNotifier>(
53	    () => SessionExpiryNotifierImpl(),
54	    dispose: (notifier) => notifier.dispose(),
55	  );
56	
57	  sl.registerLazySingleton<Dio>(() {
58	    final dio = Dio(
59	      BaseOptions(
60	        // Design note (docs/input is silent on exact numbers): a stalled
61	        // connection must still fail instead of hanging indefinitely.
62	        connectTimeout: const Duration(seconds: 10),
63	        receiveTimeout: const Duration(seconds: 30),
64	        sendTimeout: const Duration(seconds: 30),
65	      ),
66	    );
67	    dio.interceptors.add(
68	      HeaderInterceptor(
69	        anonKey: supabaseAnonKey,
70	        accessTokenProvider: sl<AccessTokenProvider>(),
71	      ),
72	    );
73	    dio.interceptors.add(RetryInterceptor(dio));
74	    return dio;
75	  });
76	
77	  sl.registerLazySingleton<ApiClient>(
78	    () => ApiClient(
79	      dio: sl<Dio>(),
80	      urlBuilder: sl<UrlBuilder>(),
81	      sessionExpiryNotifier: sl<SessionExpiryNotifier>(),
82	    ),
83	  );
84	
85	  registerAuthFeature();
86	  registerVaultFeature();
87	  registerAccountFeature();
88	
89	  // Story 3.1 — the app's first `hive_ce` usage: `initFlutter()` must
90	  // complete before `registerEntriesFeature()` opens its box (Code Map).
91	  await Hive.initFlutter();
92	  await registerEntriesFeature();
93	  registerCaptureFeature();
94	  // spec-6-1 — `registerChatFeature()` opens its own two Hive boxes, same
95	  // `Hive.initFlutter()`-must-run-first requirement `registerEntriesFeature()`
96	  // already documents for itself.
97	  await registerChatFeature();
98	}
99	
100	/// Test/teardown helper — resets the single `get_it` instance so each test
101	/// bootstraps its own clean registrations.
102	Future<void> resetCoreDependencies() => sl.reset();
