676	/// spec-5-2 — the active-filter chip row rendered under the search bar
677	/// whenever `MeusRegistrosCubit.hasActiveFilters` is true (Boundaries);
678	/// reads the cubit's own filter fields directly rather than threading them
679	/// through `MeusRegistrosState` (Design Notes: a filter change already
680	/// re-emits a new state via `applyFilters()`/`clearFilters()`, so this
681	/// widget's own `BlocBuilder` ancestor already rebuilds it in lockstep).
682	class _ActiveFiltersRow extends StatelessWidget {
683	  const _ActiveFiltersRow({required this.cubit, required this.searchCubit});
684	
685	  final MeusRegistrosCubit cubit;
686	
687	  /// spec-5-3 — `MeusRegistrosScreen`'s own bridge to
688	  /// `EntriesSearchCubit` (Design Notes): every filter-mutating call site
689	  /// below also calls this cubit's own `updateFilters()`, right alongside
690	  /// [cubit]'s `applyFilters()`/`clearFilters()`, so a filter change
691	  /// during an active search is reflected there too.
692	  final EntriesSearchCubit searchCubit;
693	
694	  @override
695	  Widget build(BuildContext context) {
696	    final source = cubit.activeSource;
697	    final dateFrom = cubit.activeDateFrom;
698	    final dateTo = cubit.activeDateTo;
699	    final dateRangePreset = cubit.activeDateRangePreset;
700	    final hasDateRange = dateFrom != null && dateTo != null;
701	    return Padding(
702	      padding: const EdgeInsets.fromLTRB(
703	        DesignTokens.spacingMd,
704	        DesignTokens.spacingSm,
705	        DesignTokens.spacingMd,
706	        0,
707	      ),
708	      child: Wrap(
709	        crossAxisAlignment: WrapCrossAlignment.center,
710	        spacing: DesignTokens.spacingSm,
711	        runSpacing: DesignTokens.spacingSm,
712	        children: [
713	          if (source != null)
714	            _ActiveFilterChip(
715	              label: entrySourceLabel(source),
716	              // I/O matrix: "Remove one of two active chips" — re-applies
717	              // every *other* active filter exactly as it stood, dropping
718	              // only this one. Round-2 review fix: passes `dateRangePreset`
719	              // back in too — otherwise the still-active date range would
720	              // revert to the cubit's default "Todo o período" preset.
721	              onRemove: () {
722	                cubit.applyFilters(
723	                  dateFrom: dateFrom,
724	                  dateTo: dateTo,
725	                  dateRangePreset: dateRangePreset,
726	                );
727	                searchCubit.updateFilters(dateFrom: dateFrom, dateTo: dateTo);
728	              },
729	            ),
730	          if (hasDateRange)
731	            _ActiveFilterChip(
732	              label: dateRangePresetLabel(dateRangePreset),
733	              onRemove: () {
734	                cubit.applyFilters(source: source);
735	                searchCubit.updateFilters(source: source);
736	              },
737	            ),
738	          // Correction: `cerne-prototype.html`'s own active-filters row
739	          // renders "Limpar filtros" as a plain small mono-caption link
740	          // on the same row as the chips, not a full `AppButton` on its
741	          // own line.
742	          GestureDetector(
743	            onTap: () {
744	              // I/O matrix: "Clear all filters" — restores the full
745	              // unfiltered list in place, no reload/re-mount (Boundaries).
746	              cubit.clearFilters();
747	              searchCubit.updateFilters();
748	            },
749	            child: Text(
750	              'Limpar filtros',
751	              style: DesignTokens.textMonoCaption.copyWith(
752	                color: DesignTokens.colorTextSecondary,
753	              ),
754	            ),
755	          ),
756	        ],
757	      ),
758	    );
759	  }
760	}
