192	  /// The shared SSE-consumption step behind [sendMessage]/[retryMessage]
193	  /// (Code Map: "extract shared SSE buffer/parse helper") — buffers raw
194	  /// text from [chunks] until a full `\n\n`-terminated SSE event block is
195	  /// available, then hands each complete block to [_parseEvent].
196	  ///
197	  /// Terminal handling (Design Notes/I/O matrix):
198	  /// - An upstream `Left` (an offline/timeout/etc. failure from the
199	  ///   underlying HTTP call itself, surfaced by `ApiClient.postStream`) is
200	  ///   forwarded as-is and ends the stream immediately — covers "Send
201	  ///   while offline" (an immediate `Left(Failure.networkOffline)`, never
202	  ///   queued) and any other transport-level failure.
203	  /// - A parsed `done` event or an in-band `error` event (mapped via
204	  ///   [Failure.fromCode]) both end the stream right after being emitted
205	  ///   — the backend's own SSE ordering guarantees neither is followed by
206	  ///   anything else worth reading.
207	  /// - If the underlying byte stream simply ends (no exception, no
208	  ///   `done`/`error` event ever parsed) — a mid-stream drop — a single
209	  ///   trailing `Left(Failure.networkTimeout)` is emitted, since the
210	  ///   closed, 13-code taxonomy has no dedicated "dropped stream" code
211	  ///   (Design Notes).
212	  Stream<Either<Failure, ChatStreamEvent>> _consumeSse(
213	    Stream<Either<Failure, String>> chunks,
214	  ) async* {
215	    var buffer = '';
216	    await for (final chunkResult in chunks) {
217	      final upstreamFailure = chunkResult.fold((f) => f, (_) => null);
218	      if (upstreamFailure != null) {
219	        yield left(upstreamFailure);
220	        return;
221	      }
222	      final chunk = chunkResult.fold((_) => '', (s) => s);
223	      // Normalize after concatenation, not per-chunk — a `\r\n` line
224	      // ending split exactly across two chunks (one ends `\r`, the next
225	      // starts `\n`) would otherwise survive unnormalized in `buffer`.
226	      buffer = (buffer + chunk).replaceAll('\r\n', '\n');
227	
228	      var separatorIndex = buffer.indexOf('\n\n');
229	      while (separatorIndex != -1) {
230	        final rawEvent = buffer.substring(0, separatorIndex);
231	        buffer = buffer.substring(separatorIndex + 2);
232	        if (rawEvent.trim().isNotEmpty) {
233	          final parsed = _parseEvent(rawEvent);
234	          if (parsed != null) {
235	            final isDone = parsed.fold((_) => false, (e) => e is ChatDoneEvent);
236	            final isFailure = parsed.isLeft();
237	            yield parsed;
238	            // A `done`/in-band-error exit is a clean terminal event, not
239	            // a drop — return directly, skipping the trailing
240	            // mid-stream-drop failure below.
241	            if (isDone || isFailure) {
242	              return;
243	            }
244	          }
245	        }
246	        separatorIndex = buffer.indexOf('\n\n');
247	      }
248	    }
249	    // Reached only if the byte stream ended on its own (no exception, no
250	    // `done`/`error` event ever parsed) — a mid-stream drop.
251	    yield left(
252	      const Failure.networkTimeout(
253	        message: 'Connection closed before the response completed',
254	      ),
255	    );
256	  }
257	
258	  /// Parses one complete, blank-line-delimited SSE event block into a
259	  /// [ChatStreamEvent] (`Right`), an in-band failure (`Left`), or `null`
260	  /// when the block should simply be skipped — a `context` event
261	  /// (Boundaries: "received and discarded", never surfaced as a
262	  /// [ChatStreamEvent]) or any event name this client doesn't recognize
263	  /// (forward-compatible: an unknown future event type is ignored rather
264	  /// than treated as malformed). Any JSON-decode failure, or a decoded
265	  /// payload missing the field a known event name requires, maps to
266	  /// [Failure.malformedResponse] (Design Notes: "anything that fails to
267	  /// parse as expected becomes `Failure.malformedResponse`, never a
268	  /// crash") — never a thrown exception escaping into [sendMessage]'s own
269	  /// `async*` body.
270	  Either<Failure, ChatStreamEvent>? _parseEvent(String rawEvent) {
271	    String? eventName;
272	    final dataLines = <String>[];
273	    for (final line in rawEvent.split('\n')) {
274	      if (line.startsWith('event:')) {
275	        eventName = line.substring('event:'.length).trim();
276	      } else if (line.startsWith('data:')) {
277	        var value = line.substring('data:'.length);
278	        if (value.startsWith(' ')) {
279	          value = value.substring(1);
280	        }
281	        dataLines.add(value);
282	      }
283	    }
284	    if (eventName == null) {
285	      return null;
286	    }
287	    final dataStr = dataLines.join('\n');
288	
289	    switch (eventName) {
290	      case 'message_created':
291	        try {
292	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
293	          return right(ChatMessageCreatedEvent(json['id'] as String));
294	        } catch (error) {
295	          return left(
296	            Failure.malformedResponse(
297	              message: 'malformed message_created event: $error',
298	            ),
299	          );
300	        }
301	      case 'context':
302	        // Boundaries: "never rendering the SSE `context` event's
303	        // retrieval/citation data" — received and discarded.
304	        return null;
305	      case 'token':
306	        try {
307	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
308	          return right(ChatTokenEvent(json['delta'] as String));
309	        } catch (error) {
310	          return left(
311	            Failure.malformedResponse(
312	              message: 'malformed token event: $error',
313	            ),
314	          );
315	        }
316	      case 'done':
317	        return right(const ChatDoneEvent());
318	      case 'error':
319	        try {
320	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
321	          final code = json['code'] as String;
322	          final message = json['message'];
323	          return left(
324	            Failure.fromCode(
325	              code,
326	              message is String ? message : 'Unknown error',
327	            ),
328	          );
329	        } catch (error) {
330	          return left(
331	            Failure.malformedResponse(
332	              message: 'malformed error event: $error',
333	            ),
334	          );
335	        }
336	      default:
337	        // Forward-compatible: an event name this client doesn't
338	        // recognize is skipped, not treated as malformed.
339	        return null;
340	    }
341	  }
342	}
