122	  /// duration, so without this a fast double-tap on Salvar could fire a
123	  /// second, un-deduplicated `create` call before the sheet finishes
124	  /// closing.
125	  Future<void> save() async {
126	    final text = state.text.trim();
127	    if (text.isEmpty || state is TextEntrySaving || state is TextEntrySaved) {
128	      return;
129	    }
130	    final activeTab = state.activeTab;
131	    emit(TextEntrySaving(activeTab: activeTab, text: text));
