136	    // Mirrors `AccountSettingsCubit.toggleBiometric`'s own guard: this
137	    // cubit's `dispose:`/`close()` can race the awaited call above (e.g.
138	    // the modal's barrier is dismissed mid-save) — `emit()` after `close()`
139	    // would otherwise throw.
140	    if (isClosed) {
141	      return;
142	    }
143	    result.match(
144	      (failure) => emit(
145	        TextEntryError(activeTab: activeTab, text: text, message: failure.message),
146	      ),
147	      (_) => emit(TextEntrySaved(activeTab: activeTab, text: text)),
148	    );
149	  }
150	}
